function actualizar(valor) {
  const R = Math.min(10, Math.max(1, Number(valor) || 5));
  const I = 2;
  const V = I * R;
  ui.patch("voltaje", { text: "Voltaje: " + V + " V" });
  ui.patch("detalle", { text: "V = 2 A · " + R + " Ω = " + V + " V" });
  ui.plot("grafica", {
    points: [[0, 0], [1, R], [2, V], [3, 3 * R], [4, 4 * R], [5, 5 * R]],
    label: "V frente a I para R = " + R + " Ω; punto de operación en I = 2 A, V = " + V + " V"
  });
  state.write({ resistencia: R });
}

ui.on("resistencia", "input", function (valor) {
  actualizar(valor);
});

actualizar(5);
